Both workers already acquire the locks in the same order (`a` then `b`), so they cannot deadlock by each holding one lock while waiting for the other. Here is the program with that ordering made explicit and both guards explicitly released before the worker returns:

```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn critical_work(a: &Mutex<()>, b: &Mutex<()>) -> usize {
    // All workers acquire locks in the same order: a, then b.
    let guard_a = a.lock().unwrap();
    let guard_b = b.lock().unwrap();

    // Critical work while holding both locks.
    let result = 1;

    drop(guard_b);
    drop(guard_a);

    result
}

fn t1(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) -> usize {
    critical_work(&a, &b)
}

fn t2(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) -> usize {
    critical_work(&a, &b)
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let h1 = thread::spawn(move || t1(a1, b1));

    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);
    let h2 = thread::spawn(move || t2(a2, b2));

    let result1 = h1.join().unwrap();
    let result2 = h2.join().unwrap();

    println!("DONE t1={} t2={}", result1, result2);
}
