use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct State {
    permits: usize,
    next_ticket: u64,
    serving_ticket: u64,
}

struct Semaphore {
    state: Mutex<State>,
    available: Condvar,
}

impl Semaphore {
    fn new(permits: usize) -> Self {
        Self {
            state: Mutex::new(State {
                permits,
                next_ticket: 0,
                serving_ticket: 0,
            }),
            available: Condvar::new(),
        }
    }

    fn acquire(&self) -> Permit<'_> {
        let mut state = self.state.lock().unwrap();
        let ticket = state.next_ticket;
        state.next_ticket += 1;

        while ticket != state.serving_ticket || state.permits == 0 {
            state = self.available.wait(state).unwrap();
        }

        state.permits -= 1;
        Permit { semaphore: self }
    }

    fn release(&self) {
        let mut state = self.state.lock().unwrap();
        state.permits += 1;
        state.serving_ticket += 1;
        drop(state);

        self.available.notify_all();
    }
}

struct Permit<'a> {
    semaphore: &'a Semaphore,
}

impl Drop for Permit<'_> {
    fn drop(&mut self) {
        self.semaphore.release();
    }
}

fn w1(s: Arc<Semaphore>) {
    for _ in 0..2 {
        let permit = s.acquire();
        thread::yield_now();
        drop(permit);
    }
}

fn w2(s: Arc<Semaphore>) {
    for _ in 0..2 {
        let permit = s.acquire();
        thread::yield_now();
        drop(permit);
    }
}

fn main() {
    let s = Arc::new(Semaphore::new(1));

    let s1 = Arc::clone(&s);
    let t1 = thread::spawn(move || w1(s1));

    let s2 = Arc::clone(&s);
    let t2 = thread::spawn(move || w2(s2));

    t1.join().unwrap();
    t2.join().unwrap();

    println!("DONE done=1");
}
```

The ticket order prevents a newly arriving worker from repeatedly overtaking a waiter. The permit guard still releases the permit on every exit path, and `Condvar::wait` releases the mutex while a worker waits, allowing the holder to release the permit.

