use std::sync::atomic::{AtomicI32, Ordering};
use std::sync::Arc;
use std::thread;

fn w1(c: Arc<AtomicI32>) {
    loop {
        let observed = c.load(Ordering::SeqCst);
        let old = c
            .compare_exchange(
                observed,
                observed + 1,
                Ordering::SeqCst,
                Ordering::SeqCst,
            )
            .unwrap_or_else(|old| old);

        if old == observed {
            return;
        }
    }
}

fn w2(c: Arc<AtomicI32>) {
    loop {
        let observed = c.load(Ordering::SeqCst);
        let old = c
            .compare_exchange(
                observed,
                observed + 1,
                Ordering::SeqCst,
                Ordering::SeqCst,
            )
            .unwrap_or_else(|old| old);

        if old == observed {
            return;
        }
    }
}

